import React from 'react';
import PropTypes from 'prop-types';
import render from '../app-target';
import UserData from './users';

import {APP_NAME} from '../../lib/constants/brand';
import {detectTheme} from '../../lib/themes/themePersistance';

const theme = detectTheme();
document.documentElement.setAttribute('data-theme', theme.id || (theme.isDark ? 'dark' : 'light'));
document.documentElement.lang = 'en';

const User = ({image, text, href}) => (
    <a
        href={href}
        target="_blank"
        rel="noreferrer"
        className="user"
    >
        <img
            loading="lazy"
            className="user-image"
            src={image}
            width="60"
            height="60"
        />
        <div className="user-info">
            {text}
        </div>
    </a>
);
User.propTypes = {
    image: PropTypes.string.isRequired,
    text: PropTypes.string.isRequired,
    href: PropTypes.string
};

const UserList = ({users}) => (
    <div className="users">
        {users.map((data, index) => (
            <User
                key={index}
                {...data}
            />
        ))}
    </div>
);
UserList.propTypes = {
    users: PropTypes.arrayOf(PropTypes.object)
};

const Credits = () => (
    <>
        <style>{`
            :root,
            [data-theme="dark"] {
                --bg-color: #1a1a2e;
                --text-color: #e4e4e7;
                --accent-color: #75C1C4;
                --secondary-bg: #252542;
                --card-bg: rgba(37, 37, 66, 0.8);
                --border-color: rgba(117, 193, 196, 0.2);
                --hover-bg: rgba(117, 193, 196, 0.1);
            }

            [data-theme="light"] {
                --bg-color: #f8fafc;
                --text-color: #1e293b;
                --accent-color: #75C1C4;
                --secondary-bg: #e2e8f0;
                --card-bg: rgba(255, 255, 255, 0.95);
                --border-color: rgba(117, 193, 196, 0.3);
                --hover-bg: rgba(117, 193, 196, 0.08);
            }

            * {
                margin: 0;
                padding: 0;
                box-sizing: border-box;
            }

            body {
                background: var(--bg-color);
                background-image: 
                    radial-gradient(circle at 20% 80%, rgba(117, 193, 196, 0.05) 0%, transparent 50%),
                    radial-gradient(circle at 80% 20%, rgba(117, 193, 196, 0.03) 0%, transparent 50%),
                    radial-gradient(rgba(255, 255, 255, 0.02) 1px, transparent 1px);
                background-size: 100% 100%, 100% 100%, 32px 32px;
                font-family: "Inter", system-ui, -apple-system, "Segoe UI", "Helvetica Neue", "Noto Sans", Helvetica, Arial, sans-serif;
                color: var(--text-color);
                line-height: 1.6;
                min-height: 100vh;
                padding: 2rem;
            }

            [data-theme="light"] body {
                background-image: 
                    radial-gradient(circle at 20% 80%, rgba(117, 193, 196, 0.08) 0%, transparent 50%),
                    radial-gradient(circle at 80% 20%, rgba(117, 193, 196, 0.05) 0%, transparent 50%),
                    radial-gradient(rgba(0, 0, 0, 0.02) 1px, transparent 1px);
            }

            main {
                max-width: 700px;
                width: 100%;
                margin: 0 auto;
            }

            .card {
                background: var(--card-bg);
                border: 1px solid var(--border-color);
                border-radius: 24px;
                padding: 3rem;
                box-shadow: 
                    0 8px 32px rgba(0, 0, 0, 0.15),
                    0 0 0 1px rgba(117, 193, 196, 0.1);
                position: relative;
                overflow: hidden;
            }

            .header {
                margin-bottom: 2rem;
                text-align: center;
            }

            h1 {
                font-size: 2.5rem;
                font-weight: 700;
                letter-spacing: -0.02em;
                margin-top: 0;
                margin-bottom: 0.5rem;
                background: linear-gradient(135deg, var(--accent-color), #98D8C8);
                -webkit-background-clip: text;
                -webkit-text-fill-color: transparent;
                background-clip: text;
            }

            section {
                margin-bottom: 2rem;
            }

            section:last-child {
                margin-bottom: 0;
            }

            h2 {
                font-size: 1.3rem;
                font-weight: 600;
                color: var(--accent-color);
                margin-bottom: 0.75rem;
                padding-bottom: 0.25rem;
                border-bottom: 2px solid var(--border-color);
            }

            p {
                margin: 0.75rem 0;
                font-weight: 450;
                color: var(--text-color);
                font-size: 1rem;
                opacity: 0.9;
            }

            a {
                color: var(--accent-color);
                text-decoration: none;
                font-weight: 600;
                border-bottom: 2px solid transparent;
                transition: all 0.25s ease;
                padding-bottom: 2px;
            }

            a:hover {
                color: #98D8C8;
                border-bottom-color: var(--accent-color);
            }

            .users {
                display: flex;
                flex-direction: row;
                flex-wrap: wrap;
                gap: 12px;
            }

            .user {
                display: flex;
                align-items: center;
                width: calc(50% - 6px);
                padding: 12px;
                border-radius: 12px;
                font-size: 1.1rem;
                color: var(--text-color) !important;
                text-decoration: none;
                transition: all 0.25s ease;
                background: var(--secondary-bg);
                border: 1px solid transparent;
            }

            .user:hover {
                background: var(--hover-bg);
                border-color: var(--accent-color);
                transform: translateY(-2px);
            }

            .user-image {
                margin-right: 12px;
                border-radius: 50%;
                object-fit: cover;
                border: 2px solid var(--accent-color);
            }

            .user-info {
                font-weight: 500;
            }

            @media (max-width: 720px) {
                body {
                    padding: 1rem;
                }

                .card {
                    padding: 2rem 1.5rem;
                    border-radius: 20px;
                }

                h1 {
                    font-size: 2rem;
                }

                .user {
                    width: 100%;
                }
            }
        `}</style>
        <main>
            <div className="card">
                <div className="header">
                    <h1>{APP_NAME} Credits</h1>
                </div>
                <section>
                    <p>
                        The {APP_NAME} project is made possible by the work of many volunteers.
                    </p>
                </section>
                {APP_NAME !== 'TurboWarp' && (
                    <section>
                        <h2>TurboWarp</h2>
                        <p>
                            {APP_NAME} is based on <a href="https://turbowarp.org/">TurboWarp</a>.
                        </p>
                    </section>
                )}
                <section>
                    <h2>Scratch</h2>
                    <p>
                        {APP_NAME} is based on the work of the <a href="https://scratch.mit.edu/credits">Scratch contributors</a> but is not endorsed by Scratch in any way.
                    </p>
                    <p>
                        <a href="https://scratch.mit.edu/donate">
                            Donate to support Scratch.
                        </a>
                    </p>
                </section>
                <section>
                    <h2>Contributors</h2>
                    <UserList users={UserData.contributors} />
                </section>
                <section>
                    <h2>Addons</h2>
                    <UserList users={UserData.addonDevelopers} />
                </section>
                <section>
                    <h2>Bilup Extension Gallery</h2>
                    <UserList users={UserData.extensionDevelopers} />
                </section>
                <section>
                    <h2>Documentation</h2>
                    <UserList users={UserData.docs} />
                </section>
                <section>
                    <h2>Translators</h2>
                    <UserList users={UserData.translators} />
                </section>
                <section>
                    <p>
                        <i>
                            Individual contributors and organizations are listed in no particular order.
                            The order is randomized each visit.
                        </i>
                    </p>
                </section>
            </div>
        </main>
    </>
);

render(<Credits />);
